/** Where a ray from o along d first crosses a closed polygon (local coordinates). */
function orbitRayHit(poly, o, d) {
  let best = null;
  for (let i = 0; i < poly.length; i++) {
    const p = poly[i], q = poly[(i + 1) % poly.length], e = [q[0] - p[0], q[1] - p[1]];
    const den = d[0] * e[1] - d[1] * e[0]; if (Math.abs(den) < 1e-9) continue;
    const w = [p[0] - o[0], p[1] - o[1]], t = (w[0] * e[1] - w[1] * e[0]) / den, s = (w[0] * d[1] - w[1] * d[0]) / den;
    if (t > 1 && s >= -1e-9 && s <= 1 + 1e-9 && (best === null || t < best)) best = t;
  }
  return best === null ? null : [o[0] + best * d[0], o[1] + best * d[1]];
}
function orbitInside(poly, p) {
  let c = false;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) { const a = poly[i], b = poly[j]; if ((a[1] > p[1]) !== (b[1] > p[1]) && p[0] < (b[0] - a[0]) * (p[1] - a[1]) / (b[1] - a[1]) + a[0]) c = !c; }
  return c;
}
function orbitEdgeDist(poly, p) {
  let m = Infinity;
  for (let i = 0; i < poly.length; i++) { const a = poly[i], b = poly[(i + 1) % poly.length], e = [b[0] - a[0], b[1] - a[1]], L2 = e[0] * e[0] + e[1] * e[1];
    const t = Math.max(0, Math.min(1, ((p[0] - a[0]) * e[0] + (p[1] - a[1]) * e[1]) / L2)); m = Math.min(m, Math.hypot(p[0] - a[0] - t * e[0], p[1] - a[1] - t * e[1])); }
  return m;
}

export function buildOrbitSample() {
  const doc = newDocument("Orbit");
  const ed = new Editor(doc);
  const add = (element) => { const r = ed.apply({ op: "add", element }, { regenerate: false }); if (!r.ok) throw new Error(`${element.id || element.type}: ${r.error}`); return r.id; };
  const rnd = p => [Math.round(p[0]), Math.round(p[1])];
  const line = (a, b) => ({ type: "line", start: rnd(a), end: rnd(b) });
  add({ id: "L1", type: "Level", name: "Typical Floor", args: { name: "Typical Floor", elevation: 0 } });
  doc.meta.name = "Orbit";
  addTestFitStyles(doc);
  const vr = { top: 2300, cut: 1200, bottom: -500, depth: -500 };
  const CLEAR = 3200;

  // ---------------------------------------------------------------- site: boundary, and the bubble diagram as context
  const deg = r => ((r * 180 / Math.PI) % 360 + 360) % 360;
  const segCurve = s => s.k === "L" ? line(s.a, s.b) : (() => { const a0 = deg(Math.min(s.a0, s.a1)), sw = Math.abs(s.a1 - s.a0) * 180 / Math.PI; return { type: "arc", centre: rnd(s.c), radius: Math.round(s.r), start: +a0.toFixed(5), end: +((a0 + sw) % 360).toFixed(5), ccw: true }; })();
  const segPts = s => s.k === "L" ? [s.a, s.b] : [0, 0.5, 1].map(f => { const t = s.a0 + (s.a1 - s.a0) * f; return [s.c[0] + s.r * Math.cos(t), s.c[1] + s.r * Math.sin(t)]; });
  const allB = HOTEL_DXF.boundary.flatMap(segPts), bx = allB.map(p => p[0]), by = allB.map(p => p[1]);
  const siteRect = [Math.min(...bx) - 20000, Math.min(...by) - 20000, Math.max(...bx) + 20000, Math.max(...by) + 20000].map(Math.round);
  add({ id: "V-SITE", type: "PlanView", name: "Orbit — Site, Typical Floor", args: { level: { ref: "L1" }, scale: 2500, viewRange: vr, detailLevel: "Coarse", style: { ref: "VS-HOTEL-SITE" }, clip: { rect: siteRect, visible: false, active: true } } });
  let dl = 0;
  HOTEL_DXF.boundary.forEach(s => add({ id: `DL${++dl}`, type: "DetailLine", args: { curve: segCurve(s), pen: "medium", lineStyle: "Centre", view: { ref: "V-SITE" }, layer: "Site boundary", colour: "#C0272D" } }));
  const tint = (hex, f) => "#" + [1, 3, 5].map(i => Math.round(parseInt(hex.slice(i, i + 2), 16) * (1 - f) + 255 * f).toString(16).padStart(2, "0")).join("");
  const text = (id, content, at, view, tt = "TT-25", wrap = 40) => add({ id, type: "Text", args: { content, position: rnd(at), rotation: 0, textType: { ref: tt }, wrapWidth: wrap, leaders: [], view: { ref: view } } });
  let fr = 0;
  const centroid = pts => { let a = 0, x = 0, y = 0; pts.forEach((p, i) => { const q = pts[(i + 1) % pts.length], c = p[0] * q[1] - q[0] * p[1]; a += c; x += (p[0] + q[0]) * c; y += (p[1] + q[1]) * c; }); return [x / (3 * a), y / (3 * a)]; };
  for (const c of ORBIT_DATA.context) {
    if (c.kind === "office") continue;
    add({ id: `FR${++fr}`, type: "FilledRegion", name: c.name, args: { boundary: c.pts, pattern: "", view: { ref: "V-SITE" }, background: tint(c.colour, 0.35), lineColour: tint(c.colour, 0.1) } });
    if (c.kind !== "fb" && c.name !== "MM") text(`TX-C${fr}`, c.name.toUpperCase(), centroid(c.pts), "V-SITE", "TT-25", 30);
  }
  text("TX-WIP", "ORBIT — WORK IN PROGRESS. TEST FIT, TYPICAL FLOOR. Hotels and office laid out; other uses shown as the bubble diagram.", [siteRect[0] + 25000, siteRect[3] - 15000], "V-SITE", "TT-35", 90);

  // ---------------------------------------------------------------- a plate in its own frame
  // P(x, y) maps the plate's frame to plan. In a rigid frame every wall is straight; in an arc frame (x across,
  // y along the arc) a wall along y is an arc, drawn as chords that break at every wall meeting it.
  const summary = [];
  function plate(key, label, scale, P, arcFrame = false, clipPts = null) {
    const view = `V-${key}`;
    const ext = (clipPts || []).map(p => P(...p)), xs = ext.map(p => p[0]), ys = ext.map(p => p[1]);
    add({ id: view, type: "PlanView", name: `${label} — Typical Floor (test fit)`, args: { level: { ref: "L1" }, scale, viewRange: vr, detailLevel: "Medium", style: { ref: "VS-HOTEL" }, clip: { rect: [Math.min(...xs) - 9000, Math.min(...ys) - 9000, Math.max(...xs) + 9000, Math.max(...ys) + 9000].map(Math.round), visible: false, active: true } } });
    let n = 0, op = 0, sp = 0, fu = 0, cl = 0;
    const specs = [], pending = [], pieces = {};
    const wall = (name, a, b, type, extra = {}) => { specs.push({ id: `S${specs.length}`, name, a, b, type, extra, alongY: arcFrame && Math.abs(a[0] - b[0]) < 1 && Math.abs(a[1] - b[1]) > 1 }); return `S${specs.length - 1}`; };
    const poly = (name, pts, type) => pts.map((p, i) => wall(name, p, pts[(i + 1) % pts.length], type));
    const finish = () => {
      const ends = specs.flatMap(w => [w.a, w.b]);
      for (const w of specs) {
        let pts = [w.a, w.b];
        if (w.alongY) {
          const lo = Math.min(w.a[1], w.b[1]), hi = Math.max(w.a[1], w.b[1]), sg = w.b[1] > w.a[1] ? 1 : -1;
          let vs = [...new Set(ends.filter(e => Math.abs(e[0] - w.a[0]) < 1 && e[1] > lo + 1 && e[1] < hi - 1).map(e => Math.round(e[1])))];
          vs = [w.a[1], ...vs, w.b[1]].sort((x, y) => sg * (x - y));
          const out = [vs[0]]; for (let i = 1; i < vs.length; i++) { const k = Math.ceil(Math.abs(vs[i] - vs[i - 1]) / 4500); for (let j = 1; j <= k; j++) out.push(vs[i - 1] + (vs[i] - vs[i - 1]) * j / k); }
          pts = out.map(v => [w.a[0], v]);
        }
        pieces[w.id] = [];
        for (let i = 0; i + 1 < pts.length; i++) {
          const id = `${key}-W${++n}`, A = P(...pts[i]), B = P(...pts[i + 1]);
          add({ id, type: "Wall", name: w.name, args: Object.assign({ centreline: line(A, B), mounting: "Centred", wallType: { ref: w.type }, baseLevel: { ref: "L1" }, baseOffset: 0, height: CLEAR, flipped: false }, w.extra), params: { Phase: "New", Comments: "Test fit - work in progress" } });
          pieces[w.id].push({ id, a: rnd(A), b: rnd(B), y0: Math.min(pts[i][1], pts[i + 1][1]), y1: Math.max(pts[i][1], pts[i + 1][1]) });
        }
      }
      for (const f of pending) f();
    };
    const hostAt = (spec, xy) => {
      const w = specs.find(s => s.id === spec), ps = pieces[spec];
      const pc = (w.alongY && ps.find(x => xy[1] >= x.y0 - 1 && xy[1] <= x.y1 + 1)) || ps[0], p = P(...xy);
      const d = [pc.b[0] - pc.a[0], pc.b[1] - pc.a[1]], Lw = Math.hypot(...d);
      return { id: pc.id, at: ((p[0] - pc.a[0]) * d[0] + (p[1] - pc.a[1]) * d[1]) / Lw, L: Lw };
    };
    const door = (spec, xy, flip, w = 915) => pending.push(() => { const h = hostAt(spec, xy), oid = `${key}-OP${++op}`, at = Math.max(w / 2 + 120, Math.min(h.L - w / 2 - 120, h.at));
      add({ id: oid, type: "Opening", args: { host: { ref: h.id }, profile: { kind: "rect", at: Math.round(at), sill: 0, w, h: 2100 }, farProfile: null, depth: "through" } });
      add({ id: `${key}-D${op}`, type: "Door", args: { fills: { ref: oid }, doorType: { ref: w > 1000 ? "T-DOOR1015" : "T-DOOR915" }, flipHand: !!flip, flipFacing: true, clearance: "None" }, params: { Phase: "New" } }); });
    const hole = (spec, xy, w) => pending.push(() => { const h = hostAt(spec, xy), at = Math.max(w / 2 + 50, Math.min(h.L - w / 2 - 50, h.at));
      add({ id: `${key}-OP${++op}`, type: "Opening", args: { host: { ref: h.id }, profile: { kind: "rect", at: Math.round(at), sill: 0, w, h: 2200 }, farProfile: null, depth: "through" } }); });
    const space = (name, xy, dept, number, quiet) => add({ id: `${key}-SP${++sp}`, type: "Space", name, args: { level: { ref: "L1" }, upperLimit: { mode: "offset", offset: CLEAR }, anchor: rnd(P(...xy)), boundaryAt: "finishFace" }, params: Object.assign({ Number: number || "", Department: dept, Occupancy: dept === "Guest room" ? 2 : 0 }, quiet ? { LabelFormat: " " } : {}) });
    const angle = (xy, alongX) => { const a = alongX ? P(xy[0] + 500, xy[1]) : P(xy[0], xy[1] + 500), b = alongX ? P(xy[0] - 500, xy[1]) : P(xy[0], xy[1] - 500); return Math.atan2(a[1] - b[1], a[0] - b[0]) * 180 / Math.PI; };
    const furn = (shape, xy, size, alongX) => add({ id: `${key}-FU${++fu}`, type: "Furniture", args: { position: rnd(P(...xy)), shape, size, rotation: Math.round(((angle(xy, alongX) % 360) + 360) % 360), level: { ref: "L1" } } });
    const stair = (x0, x1, y0, y1, alongX) => {
      const ln = (a, b) => add({ id: `${key}-DLS${++n}`, type: "DetailLine", args: { curve: line(P(...a), P(...b)), pen: "thin", lineStyle: "Solid", view: { ref: view }, layer: "Stair", colour: "#000000" } });
      const land = 1200;
      if (alongX) { const lo = Math.min(x0, x1) + land, hi = Math.max(x0, x1) - land, m = (y0 + y1) / 2; ln([lo, m], [hi, m]); for (let x = lo; x <= hi + 1; x += 280) ln([x, Math.min(y0, y1) + 150], [x, Math.max(y0, y1) - 150]); }
      else { const lo = Math.min(y0, y1) + land, hi = Math.max(y0, y1) - land, m = (x0 + x1) / 2; ln([m, lo], [m, hi]); for (let y = lo; y <= hi + 1; y += 280) ln([Math.min(x0, x1) + 150, y], [Math.max(x0, x1) - 150, y]); }
    };
    const column = xy => add({ id: `${key}-C${++cl}`, type: "Column", args: { position: rnd(P(...xy)), columnType: { ref: "T-COL400" }, baseLevel: { ref: "L1" }, height: CLEAR, rotation: Math.round(angle(xy, true)) } });
    return { view, wall, poly, finish, door, hole, space, furn, stair, column, P, xs, ys };
  }
  // a key: corridor face at depth 0; across it from a to b; xyOf(depth, across); a 2.4 × 1.9 m bath at the corridor
  const keyRoom = (T, xyOf, a, b, D, bathAtA, host, number, acrossIsX) => {
    const sg = b > a ? 1 : -1, wB = bathAtA ? a : b, other = bathAtA ? b : a, dir = bathAtA ? sg : -sg, bx = wB + dir * 1900;
    T.wall("Bath", xyOf(2400, wB), xyOf(2400, bx), "T-PART100");
    T.wall("Bath side", xyOf(0, bx), xyOf(2400, bx), "T-PART100");
    T.door(host, xyOf(0, (bx + other) / 2), !bathAtA);
    T.space("", xyOf(1200, (wB + bx) / 2), "Bath", "", true);
    T.furn("Desk", xyOf(2400 + (D - 2400) / 2, wB + dir * 1050), [1800, 2000], !acrossIsX);
    T.furn("Desk", xyOf(D - 1300, other - dir * 330), [500, 1400], acrossIsX);
    T.space("King room", xyOf(Math.min(D * 0.62, D - 1500), (a + b) / 2), "Guest room", number);
  };

  // ---------------------------------------------------------------- the oval hotels
  const ovalHotel = (key, name, e) => {
    const r = e.ang * Math.PI / 180, ax = [Math.cos(r), Math.sin(r)], ay = [-Math.sin(r), Math.cos(r)];
    const P = (x, y) => [e.c[0] + x * ax[0] + y * ay[0], e.c[1] + x * ax[1] + y * ay[1]];
    const a = e.a, b = e.b, D = 8500, yc = b - D, yi = yc - 1800;
    const fac = []; for (let i = 0; i < 120; i++) { const t = 2 * Math.PI * i / 120; fac.push([Math.round(a * Math.cos(t)), Math.round(b * Math.sin(t))]); }
    const T = plate(key, name, 400, P, false, fac);
    let keys = 0; const keyNo = () => `${key}-${String(++keys).padStart(2, "0")}`;
    const hit = (o, d) => orbitRayHit(fac, o, d);
    // keys run along the long sides as far as they stay 6 m deep; past that the tips
    const xr = a * Math.sqrt(1 - ((yc + 6000) / b) ** 2), nb = Math.round(2 * xr / 4000), bay = 2 * xr / nb;
    T.poly("Facade", fac, "T-EXTCAV300");
    const C = {}; for (const s of [-1, 1]) C[s] = T.wall("Corridor wall", [-xr, s * yc], [xr, s * yc], "T-BLOCK215");
    const E = {}; for (const t of [-1, 1]) E[t] = T.wall("End wall", hit([t * xr, 0], [0, -1]), hit([t * xr, 0], [0, 1]), "T-BLOCK215");
    for (const s of [-1, 1]) {
      for (let k = 1; k < nb; k++) { const x = -xr + k * bay; T.wall("Demising", [x, s * yc], hit([x, s * yc], [0, s]), "T-PART100"); }
      for (let k = 0; k < nb; k++) { const x0 = -xr + k * bay, x1 = x0 + bay, Dk = Math.min(b * Math.sqrt(1 - (x0 * x0) / (a * a)), b * Math.sqrt(1 - (x1 * x1) / (a * a))) - yc;
        keyRoom(T, (d, x) => [x, s * (yc + d)], x0, x1, Dk, k % 2 === 0, C[s], keyNo(), true); }
    }
    // the middle: an atrium behind a glass rail; at each end two lifts and a linen room, opening on to the cross corridor
    const xi = xr - 2400, xl = xi - 2600;
    for (const t of [-1, 1]) {
      const face = T.wall("Lift shafts", [t * xi, -yi], [t * xi, yi], "T-BLOCK215");
      T.wall("Lift shafts", [t * xl, -yi], [t * xl, yi], "T-BLOCK215");
      for (const y of [-yi / 3, yi / 3]) T.wall("Lift shafts", [t * xl, y], [t * xi, y], "T-BLOCK215");
      T.door(face, [t * xi, -2 * yi / 3], t > 0, 800); T.space("Linen and riser", [t * (xl + xi) / 2, -2 * yi / 3], "Core");
      for (const y of [0, 2 * yi / 3]) { T.hole(face, [t * xi, y], 1100); T.space("Lift", [t * (xl + xi) / 2, y], "Core"); }
      // the tip: a stair side-on to the cross corridor, two suites round it
      const xs0 = t * xr, xs1 = t * (xr + 2800);
      for (const y of [-2800, 2800]) T.wall("Stair", [xs0, y], [xs1, y], "T-BLOCK215");
      T.wall("Stair", [xs1, -2800], [xs1, 2800], "T-BLOCK215");
      T.stair(Math.min(xs0, xs1), Math.max(xs0, xs1), -2800, 2800, false); T.space("Stair", [(xs0 + xs1) / 2, 0], "Core");
      T.door(E[t], [xs0, 2000], t > 0, 1015);
      T.wall("Demising", [xs1, 0], hit([xs1, 0], [t, 0]), "T-PART100");
      for (const s of [-1, 1]) {
        T.door(E[t], [xs0, s * (2800 + yc) / 2], s * t > 0);
        const xm = t * (xr + (a - xr) * 0.45);
        T.furn("Desk", [xm, s * 5200], [1800, 2000], false); T.furn("Sofa", [t * (xr + 4200), s * (yc + 3000)], [2200, 850], true);
        T.space("Tip suite", [xm, s * 3000], "Guest room", keyNo());
      }
    }
    for (const s of [-1, 1]) T.wall("Atrium balustrade", [-xl, s * yi], [xl, s * yi], "T-GLASS30", { height: 1100 });
    for (const s of [-1, 1]) for (const t of [-1, 1]) T.wall("Lift shafts", [t * xl, s * yi], [t * xi, s * yi], "T-BLOCK215");
    T.space("Atrium", [0, 0], "Atrium");
    T.space("Corridor", [0, (yc + yi) / 2], "Circulation");
    T.finish();
    const area = Math.PI * a * b / 1e6, gia = Math.round(area - 2 * xl * 2 * yi / 1e6);
    summary.push({ name, keys, gia });
    text(`TX-${key}`, `${name.toUpperCase()} — oval ${(2 * a / 1000).toFixed(0)} × ${(2 * b / 1000).toFixed(0)} m — ${keys} keys per floor — ${gia} m² GIA per floor`, [Math.min(...T.xs) - 3000, Math.max(...T.ys) + 6000], T.view, "TT-25", 70);
    text(`TX-S${key}`, `${name}: ${keys} keys / floor`, P(0, -b - 8000), "V-SITE", "TT-25", 30);
  };
  ovalHotel("UPPER", "Upper-scale Hotel", ORBIT_DATA.hotels.upper);
  ovalHotel("USD", "USD Hotel", ORBIT_DATA.hotels.usd);

  // ---------------------------------------------------------------- the crescent: midscale hotel
  {
    const M = ORBIT_DATA.mid, R = M.R, L = R * (M.a0 - M.a1), th0 = (M.a0 + M.a1) / 2;
    // x across (negative toward the centre, the side facing the office), y along the centreline from the north-west tip
    const P = (x, y) => { const t = th0 + y / R; return [M.c[0] + (R + x) * Math.cos(t), M.c[1] + (R + x) * Math.sin(t)]; };
    const W2 = 8400, ycor = 900, Lh = L / 2;
    const T = plate("MID", "Midscale Hotel", 400, P, true, [[-W2, -Lh], [W2, -Lh], [W2, Lh], [-W2, Lh], [W2, 0], [-W2, 0]]);
    let keys = 0; const keyNo = () => `MID-${String(++keys).padStart(2, "0")}`;
    T.poly("Facade", [[-W2, -Lh], [W2, -Lh], [W2, Lh], [-W2, Lh]], "T-EXTCAV300");
    const Co = T.wall("Corridor wall", [ycor, -Lh], [ycor, Lh], "T-BLOCK215"), Ci = T.wall("Corridor wall", [-ycor, -Lh], [-ycor, Lh], "T-BLOCK215");
    // the outer (convex) side: keys end to end
    const nO = Math.round(L / 4000), bO = L / nO;
    for (let k = 1; k < nO; k++) T.wall("Demising", [ycor, -Lh + k * bO], [W2, -Lh + k * bO], "T-PART100");
    for (let k = 0; k < nO; k++) keyRoom(T, (d, y) => [ycor + d, y], -Lh + k * bO, -Lh + (k + 1) * bO, W2 - ycor, k % 2 === 0, Co, keyNo(), false);
    // the inner side: a stair at each end side-on to the corridor (the facade behind it goes to the key next door),
    // keys, and the lifts and back of house in the middle
    const sD = -ycor - 2800, core = 3900, Lst = 5600;
    for (const t of [-1, 1]) {
      const yEnd = t * Lh, yS = t * (Lh - Lst);
      T.wall("Stair", [-ycor, yS], [sD, yS], "T-BLOCK215"); T.wall("Stair", [sD, yEnd], [sD, yS], "T-BLOCK215");
      T.stair(sD, -ycor, Math.min(yEnd, yS), Math.max(yEnd, yS), false); T.space("Stair", [(sD - ycor) / 2, (yEnd + yS) / 2], "Core");
      T.door(Ci, [-ycor, yS + t * 700], t > 0, 1015);
      // keys from the stair to the core; the first wraps behind the stair
      const run = Lh - Lst - core, n = Math.floor(run / 3900), bw = run / n;
      for (let k = 1; k < n; k++) { const y = t * (Lh - Lst - k * bw); T.wall("Demising", [-ycor, y], [-W2, y], "T-PART100"); }
      for (let k = 0; k < n; k++) {
        const ya = t * (Lh - Lst - k * bw), yb = t * (Lh - Lst - (k + 1) * bw);
        if (k === 0) { // the corner key: entered beside the stair, its room behind it on the facade
          T.wall("Bath", [-ycor - 2400, yb], [-ycor - 2400, yb + t * 1900], "T-PART100"); T.wall("Bath side", [-ycor, yb + t * 1900], [-ycor - 2400, yb + t * 1900], "T-PART100");
          T.space("", [-ycor - 1200, yb + t * 950], "Bath", "", true); T.door(Ci, [-ycor, (ya + yb + t * 1900) / 2], t < 0);
          T.furn("Desk", [-W2 + 2400, t * (Lh - 3000)], [1800, 2000], true); T.furn("Sofa", [-W2 + 1200, (ya + yb) / 2], [2200, 850], false);
          T.space("Corner suite", [-W2 + 2600, (ya + yb) / 2], "Guest room", keyNo());
        } else keyRoom(T, (d, y) => [-ycor - d, y], ya, yb, W2 - ycor, k % 2 === 1, Ci, keyNo(), false);
      }
    }
    // the middle: two lifts on to the corridor, back of house behind them, a linen room through to the corridor
    const xL = -ycor - 2600;
    T.wall("Core", [-ycor, -core], [-W2, -core], "T-BLOCK215"); T.wall("Core", [-ycor, core], [-W2, core], "T-BLOCK215");
    T.wall("Lift shafts", [xL, -core], [xL, 1300], "T-BLOCK215"); const top = T.wall("Lift shafts", [-ycor, 1300], [-W2, 1300], "T-BLOCK215"); T.wall("Lift shafts", [-ycor, -1300], [xL, -1300], "T-BLOCK215");
    for (const y of [-2600, 0]) { T.hole(Ci, [-ycor, y], 1100); T.space("Lift", [(xL - ycor) / 2, y], "Core"); }
    T.door(top, [(xL - W2) / 2, 1300], false);
    T.door(Ci, [-ycor, 2600], false); T.space("Linen and riser", [(-ycor - W2) / 2, 2600], "Core");
    T.space("Back of house", [(xL - W2) / 2, -1300], "Core");
    T.space("Corridor", [0, 0], "Circulation");
    T.finish();
    const gia = Math.round(2 * W2 * L / 1e6);
    summary.push({ name: "Midscale Hotel", keys, gia });
    text("TX-MID", `MIDSCALE HOTEL — crescent ${(L / 1000).toFixed(0)} m long, ${(2 * W2 / 1000).toFixed(1)} m deep — ${keys} keys per floor — ${gia} m² GIA per floor`, [Math.min(...T.xs) - 3000, Math.max(...T.ys) + 6000], T.view, "TT-25", 70);
    text("TX-SMID", `Midscale Hotel: ${keys} keys / floor`, P(-W2 - 20000, 0), "V-SITE", "TT-25", 30);
  }

  // ---------------------------------------------------------------- the office
  {
    const O = ORBIT_DATA.office, ax = O.ax, ay = [-ax[1], ax[0]];
    const P = (x, y) => [O.c[0] + x * ax[0] + y * ay[0], O.c[1] + x * ax[1] + y * ay[1]];
    const fac = O.facade, [x0, x1, y0, y1] = O.rect;
    const T = plate("OFFICE", "Office", 500, P, false, fac);
    T.poly("Facade", fac, "T-EXTCAV300");
    // the lettable line: a corridor ring 2.4 m wide round a central block - a core at each end, an atrium between
    const cor = 2400, bx0 = x0 + cor, bx1 = x1 - cor, by0 = y0 + cor, by1 = y1 - cor, cw = 8400;
    const S = T.wall("Corridor wall", [x0, y0], [x1, y0], "T-BLOCK215"), N = T.wall("Corridor wall", [x1, y1], [x0, y1], "T-BLOCK215");
    const Wl = T.wall("Corridor wall", [x0, y1], [x0, y0], "T-BLOCK215"), El = T.wall("Corridor wall", [x1, y0], [x1, y1], "T-BLOCK215");
    const blk = {};
    for (const [k, yy] of [["S", by0], ["N", by1]]) {
      blk[k + "w"] = T.wall("Core", [bx0, yy], [bx0 + cw, yy], "T-BLOCK215");
      T.wall("Atrium balustrade", [bx0 + cw, yy], [bx1 - cw, yy], "T-GLASS30", { height: 1100 });
      blk[k + "e"] = T.wall("Core", [bx1 - cw, yy], [bx1, yy], "T-BLOCK215");
    }
    const faceW = T.wall("Core", [bx0, by0], [bx0, by1], "T-BLOCK215"), faceE = T.wall("Core", [bx1, by0], [bx1, by1], "T-BLOCK215");
    T.space("Atrium", [(bx0 + bx1) / 2, (by0 + by1) / 2], "Atrium");
    // a core (west one; the east one is the same turned half round): three lifts and a riser on the end corridor,
    // a stair side-on to the north corridor, two WCs on the south corridor
    const core = (R, face, hS, hN) => {
      const w = (n, a, b, t = "T-BLOCK215") => T.wall(n, R(a), R(b), t);
      w("Core", [bx0 + cw, by0], [bx0 + cw, by1]);
      w("Lift shafts", [bx0 + 2600, by0], [bx0 + 2600, by1]);
      for (const y of [by0 + 2400, by0 + 5000, by0 + 7600]) w("Lift shafts", [bx0, y], [bx0 + 2600, y]);
      T.door(hS, R([bx0 + 1300, by0]), false, 800); T.space("Riser", R([bx0 + 1300, by0 + 1200]), "Core");
      for (const y of [by0 + 3700, by0 + 6300, by0 + 8900]) { T.hole(face, R([bx0, Math.min(y, by1 - 700)]), 1100); T.space("Lift", R([bx0 + 1300, Math.min(y, by1 - 600)]), "Core"); }
      w("Stair", [bx0 + 2600, by1 - 2800], [bx0 + cw, by1 - 2800]);
      const s0 = R([bx0 + 2600, by1 - 2800]), s1 = R([bx0 + cw, by1]);
      T.stair(Math.min(s0[0], s1[0]), Math.max(s0[0], s1[0]), Math.min(s0[1], s1[1]), Math.max(s0[1], s1[1]), true);
      T.space("Stair", R([bx0 + 5500, by1 - 1400]), "Core"); T.door(hN, R([bx0 + cw - 700, by1]), false, 1015);
      w("WC", [bx0 + 5500, by0], [bx0 + 5500, by1 - 2800], "T-PART100");
      T.door(hS, R([bx0 + 4050, by0]), false); T.space("WC", R([bx0 + 4050, by0 + 3500]), "Core");
      T.door(hS, R([bx0 + 6950, by0]), true); T.space("Accessible WC", R([bx0 + 6950, by0 + 3500]), "Core");
    };
    core(p => p, faceW, blk.Sw, blk.Nw);
    core(([x, y]) => [x0 + x1 - x, y0 + y1 - y], faceE, blk.Ne, blk.Se);
    T.space("Common corridor", [(x0 + x1) / 2, y0 + cor / 2], "Circulation");
    // four tenancies off the corridor, split by walls from the ring's corners to the facade
    const corners = [[x0, y0, -1, -1], [x1, y0, 1, -1], [x1, y1, 1, 1], [x0, y1, -1, 1]];
    for (const [cx, cy, sx, sy] of corners) T.wall("Demising", [cx, cy], orbitRayHit(fac, [cx, cy], [sx * Math.SQRT1_2, sy * Math.SQRT1_2]), "T-BLOCK215");
    const mx = (x0 + x1) / 2, my = (y0 + y1) / 2;
    T.door(S, [mx, y0], false, 1015); T.door(N, [mx, y1], true, 1015); T.door(Wl, [x0, my], false, 1015); T.door(El, [x1, my], true, 1015);
    // along the long sides: meeting rooms each side of the way in, a reception at it
    let desks = 0;
    for (const [s, yy, host] of [[-1, y0, S], [1, y1, N]]) {
      const yf = yy + s * 3600;
      for (const side of [-1, 1]) {
        const xa = side < 0 ? x0 - 3600 : x1 + 3600, xb = mx + side * 3200;
        const front = T.wall("Meeting rooms", [xa, yf], [xb, yf], "T-GLASS30"); T.wall("Meeting rooms", [xb, yy], [xb, yf], "T-PART100");
        const n = Math.max(1, Math.round(Math.abs(xb - xa) / 4800)), w = (xb - xa) / n;
        for (let k = 1; k < n; k++) T.wall("Meeting rooms", [xa + k * w, yy], [xa + k * w, yf], "T-PART100");
        for (let k = 0; k < n; k++) { const xm = xa + (k + 0.5) * w; T.door(front, [xm + (k === 0 ? w * 0.15 : 0), yf], false); T.space(k % 3 === 1 ? "Phone booths" : "Meeting room", [xm, yy + s * 1800], "Meeting");
          if (k % 3 !== 1) T.furn("Table", [xm, yy + s * 1800], [Math.min(2600, Math.abs(w) - 1600), 1100], true); }
      }
      T.furn("Desk", [mx, yy + s * 1600], [2400, 800], true); T.furn("Sofa", [mx + 1800, yy + s * 3200], [1800, 800], true);
    }
    // benching in the daylight zone: desk pairs 3.2 m apart, clear of the facade, the meeting rooms and the demising walls
    const ringClear = ([x, y]) => x < x0 - 4800 || x > x1 + 4800 || y < y0 - 5400 || y > y1 + 5400;
    const diagClear = ([x, y]) => corners.every(([cx, cy, sx, sy]) => { const dx = x - cx, dy = y - cy; return Math.abs(dx * sy - dy * sx) / Math.SQRT2 > 1800 || dx * sx < 0 || dy * sy < 0; });
    for (let x = -60000; x <= 60000; x += 3200) for (let y = -40000; y <= 40000; y += 1600) {
      const p = [x, y];
      if (Math.round((y + 40000) / 1600) % 5 === 4) continue;      // a cross aisle after every four desk pairs
      if (!orbitInside(fac, p) || orbitEdgeDist(fac, p) < 1800 || !ringClear(p) || !diagClear(p)) continue;
      T.furn("Desk", p, [1600, 1600], false); desks += 2;
    }
    const tn = [["South tenancy", [mx, y0 - 9000]], ["North tenancy", [mx, y1 + 9000]], ["West tenancy", [x0 - 8000, my]], ["East tenancy", [x1 + 8000, my]]];
    for (const [nm, xy] of tn) T.space(nm, xy, "Workspace");
    for (let x = -54000; x <= 54000; x += 9000) for (let y = -36000; y <= 36000; y += 9000) {
      const p = [x, y]; if (orbitInside(fac, p) && orbitEdgeDist(fac, p) > 3000 && (x < x0 - 1500 || x > x1 + 1500 || y < y0 - 1500 || y > y1 + 1500)) T.column(p);
    }
    T.finish();
    let A = 0; fac.forEach((p, i) => { const q = fac[(i + 1) % fac.length]; A += p[0] * q[1] - q[0] * p[1]; });
    const gia = Math.round(Math.abs(A) / 2e6 - (bx1 - bx0 - 2 * cw) * (by1 - by0) / 1e6);
    summary.push({ name: "Office", tenancies: 4, desks, gia });
    text("TX-OFFICE", `OFFICE — ${gia} m² GIA per floor — four tenancies off a common corridor — ${desks} desks`, [Math.min(...T.xs) - 3000, Math.max(...T.ys) + 7000], T.view, "TT-25", 80);
    text("TX-SOFFICE", `Office: four tenancies, ${desks} desks / floor`, P(0, 0), "V-SITE", "TT-25", 30);
  }

  add({ id: "V-3D", type: "View3D", name: "Orbit — 3D", args: { camera: { azimuth: 210, elevation: 40, target: [40000, -120000, 0] }, scale: 1000, style: { ref: "VS-PRESENTATION" }, visualStyle: "Shaded" } });
  add({ id: "SC-ROOMS", type: "Schedule", name: "Room Schedule", args: { of: "IfcSpace", fields: ["Number", "Name", "Department", "Area"] } });
  add({ id: "SH-O100", type: "Sheet", name: "O-100 Orbit Test Fit", args: { number: "O-100", sheetName: "Orbit — Hotels and Office Test Fit, Typical Floor (WIP)", size: "A1", orientation: "landscape", titleBlock: { ref: "SY-TB-A1" },
    viewports: [{ id: "VP1", view: { ref: "V-SITE" }, at: [150, 330], clipVisible: false }, { id: "VP2", view: { ref: "V-OFFICE" }, at: [420, 170], clipVisible: false },
      { id: "VP3", view: { ref: "V-UPPER" }, at: [420, 430], clipVisible: false }, { id: "VP4", view: { ref: "V-USD" }, at: [650, 430], clipVisible: false }, { id: "VP5", view: { ref: "V-MID" }, at: [650, 190], clipVisible: false }], revision: "P01" } });
  doc.meta.hotelSummary = summary;
  doc.graph.layout = {};
  doc.browser = { organisation: "by-discipline", expanded: ["Views", "Sheets"] };
  doc.regenerate();
  return doc;
}
